Dataspatium.assets.register("presets/api/kartverket-teig.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"kartverket-teig\",\n  \"name\": \"Kartverket eiendomskart (WFS)\",\n  \"publisher\": \"Kartverket\",\n  \"description\": \"Fastighetsskiften (teig) ur det norska fastighetsregistret (Kartverket). Begränsa alltid med ett område (bbox): hela landet är för stort att hämta.\",\n  \"docs\": \"https://kartkatalog.geonorge.no/metadata/matrikkelen-eiendomskart-teig/74340c24-1c8a-4454-b813-bfe498e80f16\",\n  \"license\": {\n    \"name\": \"NLOD 2.0\",\n    \"url\": \"https://data.norge.no/nlod/no/2.0\"\n  },\n  \"level\": 1,\n  \"country\": \"NO\",\n  \"baseUrl\": \"https://wfs.geonorge.no/skwms1/wfs.matrikkelen-eiendomskart-teig\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"family\": {\n    \"type\": \"geodata\",\n    \"kind\": \"wfs\"\n  },\n  \"endpoints\": [],\n  \"notes\": \"Lagren hämtas från tjänsten när källan öppnas (GetCapabilities respektive tjänstekatalogen). Svaren är GeoJSON i WGS 84 och öppnas som kartor.\",\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"Norwegian Mapping Authority cadastral parcels (WFS)\",\n      \"description\": \"Cadastral parcels (teig) from the Norwegian cadastre. Always limit by an area (bbox): the whole country is too large to fetch.\",\n      \"notes\": \"The layers are read from the service when the source is opened (GetCapabilities or the service directory). Answers are GeoJSON in WGS 84 and open as maps.\"\n    },\n    \"da\": {\n      \"name\": \"Kartverket ejendomskort (WFS)\",\n      \"description\": \"Ejendomsparceller (teig) fra den norske matrikel (Kartverket). Begræns altid med et område (bbox): hele landet er for stort at hente.\",\n      \"notes\": \"Lagene hentes fra tjenesten, når kilden åbnes (GetCapabilities henholdsvis tjenestekataloget). Svarene er GeoJSON i WGS 84 og åbnes som kort.\"\n    },\n    \"nb\": {\n      \"name\": \"Kartverket eiendomskart (WFS)\",\n      \"description\": \"Eiendomsteiger fra matrikkelen (Kartverket). Begrens alltid med et område (bbox): hele landet er for stort å hente.\",\n      \"notes\": \"Lagene hentes fra tjenesten når kilden åpnes (GetCapabilities respektive tjenestekatalogen). Svarene er GeoJSON i WGS 84 og åpnes som kart.\"\n    },\n    \"fi\": {\n      \"name\": \"Kartverket kiinteistökartta (WFS)\",\n      \"description\": \"Kiinteistöpalstat (teig) Norjan kiinteistörekisteristä (Kartverket). Rajaa aina alueella (bbox): koko maa on liian suuri noudettavaksi.\",\n      \"notes\": \"Tasot noudetaan palvelusta, kun lähde avataan (GetCapabilities tai palveluhakemisto). Vastaukset ovat GeoJSONia WGS 84:ssä ja avautuvat karttoina.\"\n    },\n    \"is\": {\n      \"name\": \"Fasteignakort Kartverket (WFS)\",\n      \"description\": \"Fasteignaskikar (teig) úr norsku fasteignaskránni (Kartverket). Takmarkaðu alltaf við svæði (bbox): allt landið er of stórt til að sækja.\",\n      \"notes\": \"Lögin eru sótt úr þjónustunni þegar uppsprettan er opnuð (GetCapabilities eða þjónustuskráin). Svörin eru GeoJSON í WGS 84 og opnast sem kort.\"\n    }\n  }\n}\n");
